package br.com.fiap.bank.plataforma.domain;
import java.math.BigDecimal; import java.time.LocalDateTime;
public class SolicitacaoCredito {
 private Long id; private final String cpfCliente; private final String nomeCliente; private final String tipoCredito; private final BigDecimal valorSolicitado; private final Integer quantidadeParcelas; private final BigDecimal rendaMensal; private final Integer scoreCredito; private StatusSolicitacao status; private String parecerOperador; private final Boolean scrRestricoes; private final Integer scoreBureau; private final LocalDateTime dataSolicitacao; private LocalDateTime dataAtualizacao;
 public SolicitacaoCredito(Long id,String cpfCliente,String nomeCliente,String tipoCredito,BigDecimal valorSolicitado,Integer quantidadeParcelas,BigDecimal rendaMensal,Integer scoreCredito,StatusSolicitacao status,String parecerOperador,Boolean scrRestricoes,Integer scoreBureau,LocalDateTime dataSolicitacao,LocalDateTime dataAtualizacao){this.id=id;this.cpfCliente=cpfCliente;this.nomeCliente=nomeCliente;this.tipoCredito=tipoCredito;this.valorSolicitado=valorSolicitado;this.quantidadeParcelas=quantidadeParcelas;this.rendaMensal=rendaMensal;this.scoreCredito=scoreCredito;this.status=status;this.parecerOperador=parecerOperador;this.scrRestricoes=scrRestricoes;this.scoreBureau=scoreBureau;this.dataSolicitacao=dataSolicitacao;this.dataAtualizacao=dataAtualizacao;}
 public void atribuirId(Long id){this.id=id;} public void decidir(StatusSolicitacao novo,String parecer){if(status!=StatusSolicitacao.EM_ANALISE)throw new IllegalStateException("Somente solicitações em análise podem receber decisão da mesa.");if(novo!=StatusSolicitacao.APROVADO&&novo!=StatusSolicitacao.REPROVADO)throw new IllegalArgumentException("Decisão inválida.");status=novo;parecerOperador=parecer;dataAtualizacao=LocalDateTime.now();}
 public Long getId(){return id;} public String getCpfCliente(){return cpfCliente;} public String getNomeCliente(){return nomeCliente;} public String getTipoCredito(){return tipoCredito;} public BigDecimal getValorSolicitado(){return valorSolicitado;} public Integer getQuantidadeParcelas(){return quantidadeParcelas;} public BigDecimal getRendaMensal(){return rendaMensal;} public Integer getScoreCredito(){return scoreCredito;} public StatusSolicitacao getStatus(){return status;} public String getParecerOperador(){return parecerOperador;} public Boolean getScrRestricoes(){return scrRestricoes;} public Integer getScoreBureau(){return scoreBureau;} public LocalDateTime getDataSolicitacao(){return dataSolicitacao;} public LocalDateTime getDataAtualizacao(){return dataAtualizacao;}
}
